```json
{
  "stops": [
    {
      "poi_id": "p131",
      "kind": "activity",
      "must_do_id": null,
      "note": "Đi dạo một vòng hồ, gió núi thổi mát rượi, thấy thành phố chậm lại từng nhịp."
    },
    {
      "poi_id": "p103",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "Kiến trúc như một giấc mơ uốn lượn, cứ leo lên cao rồi nhìn xuống mà xem."
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": null,
      "note": "Cuốn nem nướng rau thơm đầy tay, chấm tương béo ngậy, ngon quá."
    },
    {
      "poi_id": "p20",
      "kind": "activity",
      "must_do_id": null,
      "note": "Chợ đêm lên đèn, hít hà mùi bắp nướng và sữa đậu nành nóng, người ta đi chậm thôi."
    }
  ]
}
```

```json
{
  "stops": [
    {
      "poi_id": "p355",
      "kind": "activity",
      "must_do_id": null,
      "note": "Lên đỉnh Langbiang, gió núi và tầm mắt mở ra cả Đà Lạt bên dưới."
    },
    {
      "poi_id": "p330",
      "kind": "meal",
      "must_do_id": null,
      "note": "Ngồi xuống thở một nhịp, gọi món nóng và nhìn vườn cây xanh quanh quán."
    },
    {
      "poi_id": "p129",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thung lũng tình yêu đi thong thả, chỗ nào cũng thấy hoa và hồ nước lấp lánh."
    },
    {
      "poi_id": "p286",
      "kind": "activity",
      "must_do_id": null,
      "note": "Vườn hoa Đà Lạt rực rỡ đủ màu, dạo một vòng là đủ ngọt cả mắt."
    },
    {
      "poi_id": "p33",
      "kind": "meal",
      "must_do_id": null,
      "note": "Góc phố nhỏ ấm cúng, ngồi lâu một chút nghe người Đà Lạt kể chuyện mưa nắng."
    },
    {
      "poi_id": "p52",
      "kind": "activity",
      "must_do_id": null,
      "note": "Buổi tối ghé Lululola, cà phê thơm và không khí trẻ trung đúng chất phố núi."
    }
  ]
}
```

```json
{
  "stops": [
    {
      "poi_id": "p165",
      "kind": "activity",
      "must_do_id": null,
      "note": "Sáng ở chợ Đà Lạt là xem phố dậy, ngửi cà phê, sờ thử trái bơ sáp. Đi một vòng rồi hẵng tính chuyện ăn gì."
    },
    {
      "poi_id": "p3",
      "kind": "activity",
      "must_do_id": null,
      "note": "Nhà thờ Con Gà đứng im giữa phố, cứ ngước lên ngắm tháp chuông rồi chụp một tấm cho có hồn Đà Lạt."
    },
    {
      "poi_id": "p191",
      "kind": "activity",
      "must_do_id": "m2",
      "note": "Bánh căn ở đây nóng giòn, nước chấm đậm đà. Ngồi xuống ăn một dĩa rồi nghe cô chín kể chuyện phố núi."
    },
    {
      "poi_id": "p80",
      "kind": "meal",
      "must_do_id": null,
      "note": "Tô bánh canh cua sánh, ngọt, thơm hành phi. Ăn chậm thôi, để bụng còn đi thác."
    },
    {
      "poi_id": "p90",
      "kind": "activity",
      "must_do_id": null,
      "note": "Thác Datanla ồn ào mà mát rượi. Đi bộ xuống, nghe nước đập đá, thử máng trượt nếu thích chút phiêu lưu."
    },
    {
      "poi_id": "p284",
      "kind": "meal",
      "must_do_id": null,
      "note": "Gà đồi nướng muối ớt, ngồi nhâm nhi kiểu dân địa phương. Tối se lạnh mà có món nóng thế này là ngon quá."
    }
  ]
}
```
